import 'package:supabase_flutter/supabase_flutter.dart';

import 'models.dart';

class BookRepository {
  final SupabaseClient _supabase;

  const BookRepository(this._supabase);

  Future<List<Book>> getPublishedBooks() async {
    final data = await _supabase
        .from('books')
        .select('id, title, author, cover_url, pages(*, overlay)')
        .eq('published', true)
        .order('created_at');

    final rows = (data as List<dynamic>).whereType<Map<String, dynamic>>();
    return rows.map(Book.fromJson).toList();
  }

  Future<Book?> getBookById(String bookId) async {
    final data = await _supabase
        .from('books')
        .select('id, title, author, cover_url, pages(*, overlay)')
        .eq('id', bookId)
        .maybeSingle();

    if (data == null) {
      return null;
    }

    return Book.fromJson(Map<String, dynamic>.from(data));
  }
}

class WordTimestamp {
  final String word;
  final double start;
  final double end;

  const WordTimestamp({
    required this.word,
    required this.start,
    required this.end,
  });

  factory WordTimestamp.fromJson(Map<String, dynamic> json) {
    return WordTimestamp(
      word: json['word'] as String? ?? '',
      start: (json['start'] as num?)?.toDouble() ?? 0,
      end: (json['end'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextElement {
  final String id;
  final String text;
  final double x;
  final double y;
  final double width;
  final String fontFamily;
  final double fontSize;
  final int fontWeight;
  final String color;
  final String textAlign;
  final double rotation;
  final TextShadow? shadow;
  final TextBackground? background;

  const TextElement({
    required this.id,
    required this.text,
    required this.x,
    required this.y,
    required this.width,
    required this.fontFamily,
    required this.fontSize,
    required this.fontWeight,
    required this.color,
    required this.textAlign,
    required this.rotation,
    this.shadow,
    this.background,
  });

  factory TextElement.fromJson(Map<String, dynamic> json) {
    return TextElement(
      id: json['id'] as String? ?? '',
      text: json['text'] as String? ?? '',
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
      width: (json['width'] as num?)?.toDouble() ?? 0,
      fontFamily: json['fontFamily'] as String? ?? 'Inter',
      fontSize: (json['fontSize'] as num?)?.toDouble() ?? 0,
      fontWeight: (json['fontWeight'] as num?)?.toInt() ?? 400,
      color: json['color'] as String? ?? '#FFFFFF',
      textAlign: json['textAlign'] as String? ?? 'left',
      rotation: (json['rotation'] as num?)?.toDouble() ?? 0,
      shadow: json['shadow'] is Map<String, dynamic>
          ? TextShadow.fromJson(json['shadow'] as Map<String, dynamic>)
          : null,
      background: json['background'] is Map<String, dynamic>
          ? TextBackground.fromJson(json['background'] as Map<String, dynamic>)
          : null,
    );
  }
}

class TextShadow {
  final String color;
  final double blur;
  final double x;
  final double y;

  const TextShadow({
    required this.color,
    required this.blur,
    required this.x,
    required this.y,
  });

  factory TextShadow.fromJson(Map<String, dynamic> json) {
    return TextShadow(
      color: json['color'] as String? ?? '#000000',
      blur: (json['blur'] as num?)?.toDouble() ?? 0,
      x: (json['x'] as num?)?.toDouble() ?? 0,
      y: (json['y'] as num?)?.toDouble() ?? 0,
    );
  }
}

class TextBackground {
  final String color;
  final double? padding;
  final double? borderRadius;

  const TextBackground({required this.color, this.padding, this.borderRadius});

  factory TextBackground.fromJson(Map<String, dynamic> json) {
    return TextBackground(
      color: json['color'] as String? ?? '#000000',
      padding: (json['padding'] as num?)?.toDouble(),
      borderRadius: (json['borderRadius'] as num?)?.toDouble(),
    );
  }
}

class TextOverlayConfig {
  final int version;
  final List<TextElement> elements;

  const TextOverlayConfig({required this.version, required this.elements});

  factory TextOverlayConfig.fromJson(Map<String, dynamic> json) {
    final elements = (json['elements'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(TextElement.fromJson)
        .toList();

    return TextOverlayConfig(
      version: (json['version'] as num?)?.toInt() ?? 1,
      elements: elements,
    );
  }
}

class PageData {
  final String id;
  final int pageNumber;
  final String? textContent;
  final TextOverlayConfig? overlay;
  final String? imageUrl;
  final String? narrationUrl;
  final String? soundscapeUrl;
  final String? compositedImageUrl;
  final List<WordTimestamp>? narrationTimestamps;

  const PageData({
    required this.id,
    required this.pageNumber,
    this.textContent,
    this.overlay,
    this.imageUrl,
    this.narrationUrl,
    this.soundscapeUrl,
    this.compositedImageUrl,
    this.narrationTimestamps,
  });

  factory PageData.fromJson(Map<String, dynamic> json) {
    final rawTimestamps =
        json['narration_timestamps'] ?? json['narrationTimestamps'];
    final timestamps = rawTimestamps is List
        ? rawTimestamps
              .whereType<Map<String, dynamic>>()
              .map(WordTimestamp.fromJson)
              .toList()
        : null;

    final overlayJson = json['overlay'];

    return PageData(
      id: json['id'] as String? ?? '',
      pageNumber:
          (json['page_number'] as num?)?.toInt() ??
          (json['pageNumber'] as num?)?.toInt() ??
          0,
      textContent:
          json['text_content'] as String? ?? json['textContent'] as String?,
      overlay: overlayJson is Map<String, dynamic>
          ? TextOverlayConfig.fromJson(overlayJson)
          : null,
      imageUrl: json['image_url'] as String? ?? json['imageUrl'] as String?,
      narrationUrl:
          json['narration_url'] as String? ?? json['narrationUrl'] as String?,
      soundscapeUrl:
          json['soundscape_url'] as String? ?? json['soundscapeUrl'] as String?,
      compositedImageUrl:
          json['composited_image_url'] as String? ??
          json['compositedImageUrl'] as String?,
      narrationTimestamps: timestamps,
    );
  }
}

class Book {
  final String id;
  final String title;
  final String? author;
  final String? coverUrl;
  final List<PageData> pages;

  const Book({
    required this.id,
    required this.title,
    this.author,
    this.coverUrl,
    required this.pages,
  });

  factory Book.fromJson(Map<String, dynamic> json) {
    final pages = (json['pages'] as List<dynamic>? ?? <dynamic>[])
        .whereType<Map<String, dynamic>>()
        .map(PageData.fromJson)
        .toList();

    return Book(
      id: json['id'] as String? ?? '',
      title: json['title'] as String? ?? '',
      author: json['author'] as String?,
      coverUrl: json['cover_url'] as String? ?? json['coverUrl'] as String?,
      pages: pages,
    );
  }
}

