import 'dart:async';

import 'package:audio_session/audio_session.dart';
import 'package:just_audio/just_audio.dart';

import '../data/models.dart';

class AudioEngine {
  final AudioPlayer _narration = AudioPlayer();
  final AudioPlayer _soundscape = AudioPlayer();

  bool _initialized = false;
  Timer? _crossfadeTimer;
  String? _currentSoundscapeUrl;

  /// Whether the user has toggled narration on (independent of player state).
  bool _narrationActive = false;

  /// Whether the user has toggled soundscape on (independent of player state).
  bool _soundscapeActive = false;

  double _soundscapeTargetVolume = 0.6;

  Future<void> ensureInitialized() async {
    if (_initialized) {
      return;
    }

    final session = await AudioSession.instance;
    await session.configure(const AudioSessionConfiguration.music());

    _soundscape.setLoopMode(LoopMode.one);
    await _soundscape.setVolume(_soundscapeTargetVolume);

    _initialized = true;
  }

  // ---------------------------------------------------------------------------
  // Page loading
  // ---------------------------------------------------------------------------

  Future<void> loadPage(PageData page) async {
    await ensureInitialized();

    final futures = <Future<void>>[];

    if (page.narrationUrl != null && page.narrationUrl!.isNotEmpty) {
      futures.add(_narration.setUrl(page.narrationUrl!).then((_) {}));
    } else {
      futures.add(_narration.stop());
    }

    if (page.soundscapeUrl != null && page.soundscapeUrl!.isNotEmpty) {
      futures.add(_soundscape.setUrl(page.soundscapeUrl!).then((_) {}));
      _currentSoundscapeUrl = page.soundscapeUrl;
    } else {
      futures.add(_soundscape.stop());
      _currentSoundscapeUrl = null;
    }

    await Future.wait(futures);
  }

  // ---------------------------------------------------------------------------
  // Independent narration controls
  // ---------------------------------------------------------------------------

  Future<void> playNarration() async {
    await ensureInitialized();
    _narrationActive = true;
    await _narration.play();
  }

  Future<void> pauseNarration() async {
    _narrationActive = false;
    await _narration.pause();
  }

  Future<void> toggleNarration() async {
    if (_narrationActive) {
      await pauseNarration();
    } else {
      await playNarration();
    }
  }

  // ---------------------------------------------------------------------------
  // Independent soundscape controls
  // ---------------------------------------------------------------------------

  Future<void> playSoundscape() async {
    await ensureInitialized();
    _soundscapeActive = true;
    await _soundscape.play();
  }

  Future<void> pauseSoundscape() async {
    _soundscapeActive = false;
    await _soundscape.pause();
  }

  Future<void> toggleSoundscape() async {
    if (_soundscapeActive) {
      await pauseSoundscape();
    } else {
      await playSoundscape();
    }
  }

  // ---------------------------------------------------------------------------
  // Page transitions
  // ---------------------------------------------------------------------------

  Future<void> transitionToPage(PageData nextPage) async {
    await ensureInitialized();

    final nextNarrationUrl = nextPage.narrationUrl;
    final nextSoundscapeUrl = nextPage.soundscapeUrl;

    // --- Narration transition ---
    if (nextNarrationUrl != null && nextNarrationUrl.isNotEmpty) {
      await _narration.stop();
      await _narration.setUrl(nextNarrationUrl);
      if (_narrationActive) {
        await _narration.play();
      }
    } else {
      await _narration.stop();
    }

    // --- Soundscape transition ---
    if (nextSoundscapeUrl == null || nextSoundscapeUrl.isEmpty) {
      await _soundscape.stop();
      _currentSoundscapeUrl = null;
      return;
    }

    // Same soundscape – keep playing, nothing to do.
    if (_currentSoundscapeUrl == nextSoundscapeUrl) {
      return;
    }

    // Different soundscape – crossfade.
    _crossfadeTimer?.cancel();
    await _soundscape.setVolume(0);
    await _soundscape.setUrl(nextSoundscapeUrl);
    _currentSoundscapeUrl = nextSoundscapeUrl;

    if (_soundscapeActive) {
      await _soundscape.play();

      const steps = 15;
      const duration = Duration(milliseconds: 1500);
      final targetVolume = _soundscapeTargetVolume;
      final tick = duration ~/ steps;
      var currentStep = 0;

      _crossfadeTimer = Timer.periodic(tick, (timer) async {
        currentStep += 1;
        final progress = currentStep / steps;
        await _soundscape.setVolume(targetVolume * progress);
        if (currentStep >= steps) {
          timer.cancel();
        }
      });
    }
  }

  // ---------------------------------------------------------------------------
  // Streams
  // ---------------------------------------------------------------------------

  Stream<Duration> get narrationPosition => _narration.positionStream;
  Stream<bool> get narrationPlaying => _narration.playingStream;
  Stream<bool> get soundscapePlaying => _soundscape.playingStream;

  bool get isNarrationActive => _narrationActive;
  bool get isSoundscapeActive => _soundscapeActive;

  // ---------------------------------------------------------------------------
  // Volume
  // ---------------------------------------------------------------------------

  Future<void> setNarrationVolume(double volume) =>
      _narration.setVolume(volume);

  Future<void> setSoundscapeVolume(double volume) {
    _soundscapeTargetVolume = volume;
    return _soundscape.setVolume(volume);
  }

  // ---------------------------------------------------------------------------
  // Lifecycle
  // ---------------------------------------------------------------------------

  Future<void> dispose() async {
    _crossfadeTimer?.cancel();
    await _narration.dispose();
    await _soundscape.dispose();
  }
}

import { useRef, useCallback, useEffect, useState } from 'react';
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

export type AudioPlayerState = {
  isPlaying: boolean;
  positionMs: number;
  durationMs: number;
};

type UseAudioPlayerReturn = {
  // Narration
  narrationState: AudioPlayerState;
  loadNarration: (uri: string) => Promise<void>;
  playNarration: () => Promise<void>;
  pauseNarration: () => Promise<void>;
  seekNarration: (positionMs: number) => Promise<void>;
  setNarrationVolume: (volume: number) => Promise<void>;
  // Soundscape
  soundscapeState: AudioPlayerState;
  loadSoundscape: (uri: string) => Promise<void>;
  playSoundscape: () => Promise<void>;
  pauseSoundscape: () => Promise<void>;
  setSoundscapeVolume: (volume: number) => Promise<void>;
  // Crossfade
  crossfadeSoundscape: (newUri: string, duration?: number) => Promise<void>;
  fadeOutSoundscape: (duration?: number) => Promise<void>;
  // Cleanup
  cleanup: () => Promise<void>;
};

export function useAudioPlayer(): UseAudioPlayerReturn {
  const narrationRef = useRef<AudioPlayer | null>(null);
  const soundscapeRef = useRef<AudioPlayer | null>(null);
  const narrationSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const soundscapeSubRef = useRef<ReturnType<AudioPlayer['addListener']> | null>(null);
  const fadeIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Track the current soundscape volume for fade calculations
  const soundscapeVolumeRef = useRef<number>(0.6);

  const [narrationState, setNarrationState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  const [soundscapeState, setSoundscapeState] = useState<AudioPlayerState>({
    isPlaying: false,
    positionMs: 0,
    durationMs: 0,
  });

  // Configure audio mode for background playback
  useEffect(() => {
    setAudioModeAsync({
      playsInSilentModeIOS: true,
      staysActiveInBackground: true,
      shouldDuckAndroid: true,
    });
  }, []);

  // Narration controls
  const loadNarration = useCallback(async (uri: string) => {
    // Clean up previous narration player
    if (narrationSubRef.current) {
      narrationSubRef.current.remove();
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      narrationRef.current.remove();
      narrationRef.current = null;
    }

    const player = createAudioPlayer({ uri });

    // Subscribe to status updates for word-sync (high frequency)
    narrationSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setNarrationState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    narrationRef.current = player;
  }, []);

  const playNarration = useCallback(async () => {
    narrationRef.current?.play();
  }, []);

  const pauseNarration = useCallback(async () => {
    narrationRef.current?.pause();
  }, []);

  const seekNarration = useCallback(async (positionMs: number) => {
    narrationRef.current?.seekTo(positionMs / 1000);
  }, []);

  const setNarrationVolume = useCallback(async (volume: number) => {
    if (narrationRef.current) {
      narrationRef.current.volume = volume;
    }
  }, []);

  // Soundscape controls
  const loadSoundscape = useCallback(async (uri: string) => {
    // Clean up previous soundscape player
    if (soundscapeSubRef.current) {
      soundscapeSubRef.current.remove();
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      soundscapeRef.current.remove();
      soundscapeRef.current = null;
    }

    const player = createAudioPlayer({ uri });
    player.loop = true;
    player.volume = 0.6;
    soundscapeVolumeRef.current = 0.6;

    soundscapeSubRef.current = player.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    soundscapeRef.current = player;
  }, []);

  const playSoundscape = useCallback(async () => {
    soundscapeRef.current?.play();
  }, []);

  const pauseSoundscape = useCallback(async () => {
    soundscapeRef.current?.pause();
  }, []);

  const setSoundscapeVolume = useCallback(async (volume: number) => {
    if (soundscapeRef.current) {
      soundscapeRef.current.volume = volume;
      soundscapeVolumeRef.current = volume;
    }
  }, []);

  // Fade out over duration
  const fadeOutSoundscape = useCallback(async (duration: number = 3000) => {
    const player = soundscapeRef.current;
    if (!player) return;

    const startVolume = soundscapeVolumeRef.current;
    const steps = 20;
    const stepDuration = duration / steps;
    const volumeStep = startVolume / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const newVolume = Math.max(0, startVolume - volumeStep * currentStep);
        player.volume = newVolume;
        soundscapeVolumeRef.current = newVolume;

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);
          player.pause();
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Crossfade: fade out current, load new, fade in
  const crossfadeSoundscape = useCallback(async (newUri: string, duration: number = 1500) => {
    const oldPlayer = soundscapeRef.current;
    const oldSub = soundscapeSubRef.current;

    // Create new player at volume 0
    const newPlayer = createAudioPlayer({ uri: newUri });
    newPlayer.loop = true;
    newPlayer.volume = 0;

    // Subscribe new player to status updates
    soundscapeSubRef.current = newPlayer.addListener('playbackStatusUpdate', (status) => {
      setSoundscapeState({
        isPlaying: status.playing,
        positionMs: (status.currentTime ?? 0) * 1000,
        durationMs: (status.duration ?? 0) * 1000,
      });
    });

    // Start playing new sound
    newPlayer.play();

    // Fade out old, fade in new simultaneously
    const steps = 15;
    const stepDuration = duration / steps;
    let currentStep = 0;

    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    return new Promise<void>((resolve) => {
      fadeIntervalRef.current = setInterval(() => {
        currentStep++;
        const progress = currentStep / steps;

        // Fade in new
        newPlayer.volume = 0.6 * progress;

        // Fade out old
        if (oldPlayer) {
          try {
            oldPlayer.volume = 0.6 * (1 - progress);
          } catch {
            // Old player may already be removed
          }
        }

        if (currentStep >= steps) {
          if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

          // Cleanup old
          if (oldSub) {
            try { oldSub.remove(); } catch { /* ignore */ }
          }
          if (oldPlayer) {
            try { oldPlayer.remove(); } catch { /* ignore */ }
          }

          soundscapeRef.current = newPlayer;
          soundscapeVolumeRef.current = 0.6;
          resolve();
        }
      }, stepDuration);
    });
  }, []);

  // Cleanup all audio
  const cleanup = useCallback(async () => {
    if (fadeIntervalRef.current) clearInterval(fadeIntervalRef.current);

    if (narrationSubRef.current) {
      try { narrationSubRef.current.remove(); } catch { /* ignore */ }
      narrationSubRef.current = null;
    }
    if (narrationRef.current) {
      try { narrationRef.current.remove(); } catch { /* ignore */ }
      narrationRef.current = null;
    }

    if (soundscapeSubRef.current) {
      try { soundscapeSubRef.current.remove(); } catch { /* ignore */ }
      soundscapeSubRef.current = null;
    }
    if (soundscapeRef.current) {
      try { soundscapeRef.current.remove(); } catch { /* ignore */ }
      soundscapeRef.current = null;
    }

    setNarrationState({ isPlaying: false, positionMs: 0, durationMs: 0 });
    setSoundscapeState({ isPlaying: false, positionMs: 0, durationMs: 0 });
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  return {
    narrationState,
    loadNarration,
    playNarration,
    pauseNarration,
    seekNarration,
    setNarrationVolume,
    soundscapeState,
    loadSoundscape,
    playSoundscape,
    pauseSoundscape,
    setSoundscapeVolume,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup,
  };
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { useAudioPlayer, type AudioPlayerState } from './useAudioPlayer';
import { useLocalPreferences } from './useLocalPreferences';
import type { PageData } from '@/types';

type UseReaderAudioProps = {
  pageData: PageData | undefined;
  bookId: string;
};

type UseReaderAudioReturn = {
  isNarrationActive: boolean;
  isSoundscapeActive: boolean;
  narrationState: AudioPlayerState;
  soundscapeState: AudioPlayerState;
  toggleNarration: () => Promise<void>;
  toggleSoundscape: () => Promise<void>;
  loadNarration: (url: string) => Promise<void>;
  loadSoundscape: (url: string) => Promise<void>;
  cleanup: () => void;
};

export function useReaderAudio({ pageData }: UseReaderAudioProps): UseReaderAudioReturn {
  const {
    narrationState,
    loadNarration: loadNarrationAudio,
    playNarration,
    pauseNarration,
    soundscapeState,
    loadSoundscape: loadSoundscapeAudio,
    playSoundscape,
    pauseSoundscape,
    crossfadeSoundscape,
    fadeOutSoundscape,
    cleanup: cleanupAudio,
  } = useAudioPlayer();

  const { preferences } = useLocalPreferences();

  const [isNarrationActive, setIsNarrationActive] = useState(false);
  const [isSoundscapeActive, setIsSoundscapeActive] = useState(false);

  const introFadeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const introFadedPages = useRef(new Set<number>());
  const prevSoundscapeUrl = useRef<string | null>(null);

  const currentPage = pageData?.pageNumber ?? 1;

  const narrationAssignment = pageData?.assignments?.find((a) => a.audioType === 'narration');
  const soundscapeAssignment = pageData?.assignments?.find((a) => a.audioType === 'soundscape');
  const narrationUrl = narrationAssignment?.audioUrl || pageData?.narrationUrl;
  const soundscapeUrl = soundscapeAssignment?.audioUrl;

  // Load narration audio when page changes
  useEffect(() => {
    if (narrationUrl) {
      loadNarrationAudio(narrationUrl).then(() => {
        if (isNarrationActive) {
          playNarration();
        }
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [narrationUrl]);

  // Handle soundscape changes with crossfade
  useEffect(() => {
    if (!soundscapeUrl) return;

    if (prevSoundscapeUrl.current && prevSoundscapeUrl.current !== soundscapeUrl && isSoundscapeActive) {
      crossfadeSoundscape(soundscapeUrl);
    } else if (!prevSoundscapeUrl.current || prevSoundscapeUrl.current !== soundscapeUrl) {
      loadSoundscapeAudio(soundscapeUrl).then(() => {
        if (isSoundscapeActive) playSoundscape();
      });
    }
    prevSoundscapeUrl.current = soundscapeUrl;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [soundscapeUrl]);

  // Intro-only mode: fade out after 10 seconds
  useEffect(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }

    if (
      preferences.soundscapeMode === 'intro-only' &&
      isSoundscapeActive &&
      soundscapeUrl &&
      !introFadedPages.current.has(currentPage)
    ) {
      introFadeTimerRef.current = setTimeout(() => {
        introFadedPages.current.add(currentPage);
        fadeOutSoundscape(3000).then(() => {
          setIsSoundscapeActive(false);
        });
      }, 10000);
    }

    return () => {
      if (introFadeTimerRef.current) clearTimeout(introFadeTimerRef.current);
    };
  }, [currentPage, preferences.soundscapeMode, isSoundscapeActive, soundscapeUrl, fadeOutSoundscape]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      cleanupAudio();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleNarration = useCallback(async () => {
    if (isNarrationActive) {
      await pauseNarration();
      setIsNarrationActive(false);
    } else if (narrationUrl) {
      await playNarration();
      setIsNarrationActive(true);
    }
  }, [isNarrationActive, narrationUrl, playNarration, pauseNarration]);

  const toggleSoundscape = useCallback(async () => {
    if (isSoundscapeActive) {
      await pauseSoundscape();
      setIsSoundscapeActive(false);
    } else if (soundscapeUrl) {
      await playSoundscape();
      setIsSoundscapeActive(true);
    }
  }, [isSoundscapeActive, soundscapeUrl, playSoundscape, pauseSoundscape]);

  const loadNarration = useCallback(
    async (url: string) => {
      await loadNarrationAudio(url);
    },
    [loadNarrationAudio]
  );

  const loadSoundscape = useCallback(
    async (url: string) => {
      await loadSoundscapeAudio(url);
    },
    [loadSoundscapeAudio]
  );

  const cleanup = useCallback(() => {
    if (introFadeTimerRef.current) {
      clearTimeout(introFadeTimerRef.current);
      introFadeTimerRef.current = null;
    }
    cleanupAudio();
  }, [cleanupAudio]);

  return {
    isNarrationActive,
    isSoundscapeActive,
    narrationState,
    soundscapeState,
    toggleNarration,
    toggleSoundscape,
    loadNarration,
    loadSoundscape,
    cleanup,
  };
}

import 'package:supabase_flutter/supabase_flutter.dart';

import 'models.dart';

class BookRepository {
  final SupabaseClient _supabase;

  const BookRepository(this._supabase);

  Future<List<Book>> getPublishedBooks() async {
    final data = await _supabase
        .from('books')
        .select('id, title, author, cover_url, pages(*, scenes(soundscapes(audio_url, admin_approved)))')
        .eq('is_published', true)
        .order('inserted_at');

    final rows = (data as List<dynamic>).whereType<Map<String, dynamic>>();
    return rows.map(Book.fromJson).toList();
  }

  Future<Book?> getBookById(String bookId) async {
    final data = await _supabase
        .from('books')
        .select('id, title, author, cover_url, pages(*, scenes(soundscapes(audio_url, admin_approved)))')
        .eq('id', bookId)
        .maybeSingle();

    if (data == null) {
      return null;
    }

    return Book.fromJson(Map<String, dynamic>.from(data));
  }
}

